#!/usr/bin/env bash
#
# Offline tests for scripts/sync_version.sh's lockfile step. The script derives REPO_ROOT from its own
# location, so each case runs a COPY of it inside a scratch repo layout, never the real one, and the suite
# ends by checking the real files did not change. Fake flutter and dart executables record which one was
# asked to run, so the tests need no Flutter install and no network.
#
# What it pins down: flutter is preferred, dart is the fallback, and with neither the lock cannot be
# regenerated, which warns locally and fails under CI. A silent skip would let the drift check compare an
# untouched lock against itself and always pass.
#
set -euo pipefail

REAL_ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
FAILURES=0

pass() { echo "ok   - $1"; }
fail() { echo "FAIL - $1"; FAILURES=$((FAILURES + 1)); }
check() {
  if [ "$2" = "$3" ]; then pass "$1"; else fail "$1 (expected '$2', got '$3')"; fi
}

hash_real() {
  (cd "$REAL_ROOT" && shasum -a 256 scripts/sync_version.sh pubspec.yaml example/pubspec.yaml example/pubspec.lock \
    ios/klaviyo_flutter_sdk/Sources/klaviyo_flutter_sdk/klaviyo-sdk-configuration.plist 2>/dev/null)
}
BEFORE="$(hash_real)"

# A scratch repo with just the files the script touches.
make_repo() {
  local repo="$1"
  rm -rf "$repo"
  mkdir -p "$repo/scripts" "$repo/example" "$repo/ios/klaviyo_flutter_sdk/Sources/klaviyo_flutter_sdk"
  cp "$REAL_ROOT/scripts/sync_version.sh" "$repo/scripts/"
  printf 'name: klaviyo_flutter_sdk\nversion: 1.2.3\n' > "$repo/pubspec.yaml"
  printf 'name: example\nversion: 0.0.1\n' > "$repo/example/pubspec.yaml"
  printf 'packages:\n  klaviyo_flutter_sdk:\n    version: "0.0.1"\n' > "$repo/example/pubspec.lock"
}

# A fake tool that records its own name and "regenerates" the lock the way pub get would.
fake_tool() { # <bin dir> <name>
  mkdir -p "$1"
  cat > "$1/$2" <<FAKE
#!/usr/bin/env bash
echo "$2 \$*" >> "\$FAKE_LOG"
sed -i.bak 's/version: "[^"]*"\$/version: "'"\$(grep '^version:' ../pubspec.yaml | awk '{print \$2}')"'"/' pubspec.lock && rm -f pubspec.lock.bak
FAKE
  chmod +x "$1/$2"
}

# The base PATH holds only what the script itself runs, so the absence of flutter and dart is real.
BASE_BIN="$WORK/basebin"
mkdir -p "$BASE_BIN"
for t in bash sh env cat grep awk sed sort head tail tr cut rm mkdir cp mv date dirname basename printf test wc; do
  p="$(command -v "$t" 2>/dev/null || true)"
  [ -n "$p" ] && [ -x "$p" ] && ln -sf "$p" "$BASE_BIN/$t"
done

# run_sync <repo> <PATH> [ci]: prints "rc=<n>" then stderr; the fake log is $WORK/log
run_sync() {
  local repo="$1" path="$2" ci="${3:-}"
  : > "$WORK/log"
  local rc=0 err
  err="$(cd "$repo" && env -i HOME="$WORK" PATH="$path" FAKE_LOG="$WORK/log" ${ci:+CI=true} \
    bash scripts/sync_version.sh 2>&1 >/dev/null)" || rc=$?
  echo "rc=$rc"
  printf '%s\n' "$err"
}
lock_version() { grep 'version:' "$1/example/pubspec.lock" | tr -d ' "' ; }

# --- flutter is preferred when both are present
REPO="$WORK/r1"; make_repo "$REPO"
fake_tool "$WORK/both" flutter; fake_tool "$WORK/both" dart
result="$(run_sync "$REPO" "$WORK/both:$BASE_BIN")"
check "sync: succeeds with flutter and dart on PATH" "rc=0" "$(head -1 <<<"$result")"
check "sync: flutter is the tool that ran" "flutter pub get" "$(head -1 "$WORK/log")"
check "sync: dart did not run when flutter was there" "0" "$(grep -c '^dart' "$WORK/log" | tr -d ' ')"
check "sync: the lock now records the pubspec version" "version:1.2.3" "$(lock_version "$REPO")"

# --- dart is the fallback
REPO="$WORK/r2"; make_repo "$REPO"
fake_tool "$WORK/dartonly" dart
result="$(run_sync "$REPO" "$WORK/dartonly:$BASE_BIN")"
check "sync: succeeds with only dart" "rc=0" "$(head -1 <<<"$result")"
check "sync: dart is the tool that ran" "dart pub get" "$(head -1 "$WORK/log")"
check "sync: the lock is regenerated by the fallback too" "version:1.2.3" "$(lock_version "$REPO")"

# --- neither tool: warn locally, fail in CI, never skip silently
REPO="$WORK/r3"; make_repo "$REPO"
result="$(run_sync "$REPO" "$BASE_BIN")"
check "sync: local run with no tool still exits 0" "rc=0" "$(head -1 <<<"$result")"
if grep -q 'WARNING: neither flutter nor dart is on PATH, so example/pubspec.lock was NOT synced to 1.2.3' <<<"$result"; then
  pass "sync: local run with no tool warns that the lock was not synced"
else
  fail "sync: local run with no tool warns that the lock was not synced ($(tail -n +2 <<<"$result" | head -c 160))"
fi
check "sync: the lock is left unchanged when nothing can regenerate it" "version:0.0.1" "$(lock_version "$REPO")"

REPO="$WORK/r4"; make_repo "$REPO"
result="$(run_sync "$REPO" "$BASE_BIN" ci)"
if [ "$(head -1 <<<"$result")" = "rc=1" ] && grep -q 'example/pubspec.lock was NOT synced' <<<"$result"; then
  pass "sync: under CI with no tool the script fails and says why"
else
  fail "sync: under CI with no tool the script fails and says why ($(head -c 200 <<<"$result" | tr '\n' ' '))"
fi

# --- no lock file in the repo: nothing to sync, nothing to warn about
REPO="$WORK/r5"; make_repo "$REPO"; rm -f "$REPO/example/pubspec.lock"
result="$(run_sync "$REPO" "$BASE_BIN" ci)"
check "sync: a repo without a lockfile is not an error even under CI" "rc=0" "$(head -1 <<<"$result")"

# --- the suite never touched the real repo
check "the real repo was not modified by this suite" "$BEFORE" "$(hash_real)"

echo
if [ "$FAILURES" -gt 0 ]; then
  echo "$FAILURES test(s) failed"
  exit 1
fi
echo "All sync-version tests passed"
